(() => {
  const drive = window.__trunkDrive;
  const observations = [];
  const archive = 'Synthetic archived review';
  const archivedIds = Array.from({length: 15}, (_, index) => `review-thread-${String(index).padStart(2, '0')}`);
  const visible = element => element && element.getClientRects().length > 0 &&
    getComputedStyle(element).visibility === 'visible';
  const findVisible = selector => [...document.querySelectorAll(selector)].find(visible);
  const panel = () => findVisible('[aria-label="Review threads"]');
  const body = () => panel()?.querySelector('.review-body');
  const selectedTab = () => findVisible('[role="tab"][aria-selected="true"]')?.textContent.trim();
  const equal = (actual, expected) => JSON.stringify(actual) === JSON.stringify(expected);
  function requireValue(actual, expected, label) {
    if (!equal(actual, expected)) {
      throw Error(`${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
    }
  }
  const frame = () => new Promise(resolve => requestAnimationFrame(resolve));
  async function paint() {
    await frame();
    await frame();
  }

  function archiveDisclosure() {
    return [...document.querySelectorAll('button[aria-expanded]')]
      .find(button => visible(button) && button.textContent.trim().startsWith('Archived'));
  }

  function reading(target) {
    const pane = body();
    const threads = [...(pane?.querySelectorAll('[data-thread-id]') ?? [])];
    const card = threads.find(thread => thread.dataset.threadId === target);
    const cursor = pane?.querySelector('[data-thread-id][aria-current="true"]');
    const active = document.activeElement;
    return {
      tab: selectedTab() ?? null,
      review: panel()?.querySelector('h1')?.textContent.trim() ?? null,
      threadIds: threads.map(thread => thread.dataset.threadId),
      cursor: cursor?.dataset.threadId ?? null,
      focus: pane?.contains(active) ? active.dataset.threadId ?? null : null,
      scrollTop: pane?.scrollTop ?? null,
      viewportHeight: pane?.clientHeight ?? null,
      targetOffset: card ? card.getBoundingClientRect().top - pane.getBoundingClientRect().top : null,
      archiveExpanded: archiveDisclosure()?.getAttribute('aria-expanded') ?? null,
    };
  }

  async function record(label, target) {
    await paint();
    const value = reading(target);
    observations.push({label, ...value});
    return value;
  }

  function reviewReady(tab, title, ids) {
    const view = reading();
    return view.tab === tab && view.review === title && equal([...view.threadIds].sort(), ids);
  }

  async function waitForReview(tab, title, ids) {
    await drive.until(`window.reviewReplay.reviewReady(...${JSON.stringify([tab, title, ids])})`);
  }

  function reviewRow(title) {
    return [...document.querySelectorAll('button[title]')].find(button =>
      visible(button) && button.title.startsWith('Click to show') && button.textContent.includes(title));
  }

  async function openArchive() {
    await drive.click('button', 'Review');
    await waitForReview('review-repo', 'Synthetic control review', ['control-thread']);
    archiveDisclosure().click();
    await drive.until('window.reviewReplay.hasArchiveRow()');
    reviewRow(archive).click();
    await waitForReview('review-repo', archive, archivedIds);
  }

  function inspectOrphan(id) {
    const card = body()?.querySelector(`[data-thread-id="${id}"]`);
    const badge = card?.querySelector('.orphan-badge');
    return badge?.textContent.trim() === 'Orphaned' && badge.title.startsWith('File gone.') &&
      !card.querySelector('[aria-label="Jump to code"]')
      ? {id, badge: badge.textContent.trim(), tooltip: badge.title} : null;
  }

  async function focusThread(target) {
    panel().focus({preventScroll: true});
    const keys = [];
    for (let index = 0; index < archivedIds.length; index++) {
      drive.key('j');
      await paint();
      const next = reading(target).cursor;
      if (!next || next === keys.at(-1)) throw Error(`J stopped at ${next} before ${target}`);
      keys.push(next);
      if (next === target) return keys;
    }
    throw Error(`J did not reach ${target}`);
  }

  function inspectDiff(target, anchor) {
    const file = findVisible('[data-testid="diff-path"]')?.textContent.trim();
    const viewport = findVisible('.hunk-view .exact-virtual-viewport');
    if (file !== anchor.path || !viewport || panel()) return null;
    const line = [...viewport.querySelectorAll('.diff-line-add[data-line-path]')].find(row =>
      row.dataset.linePath === anchor.path &&
      row.querySelector(`[aria-label="Select added line ${anchor.line}"]`) &&
      row.querySelector('.diff-line-content')?.textContent.trim() ===
        `export const value${anchor.line - 1} = "${anchor.marker}";`);
    const inlineRow = line?.nextElementSibling;
    const inline = inlineRow?.matches('.inline-comment-row') &&
      inlineRow.querySelector(`[data-thread-id="${target}"].comment-card-inline`);
    if (!visible(line) || !visible(inline)) return null;

    const detail = document.querySelector('[data-testid="commit-detail"] [title="Copy SHA"]');
    const oid = detail?.textContent.trim();
    const expectedOid = anchor.oid.slice(0, 7);
    if (oid !== expectedOid) return null;

    const viewportBounds = viewport.getBoundingClientRect();
    const surfaceBounds = line.closest('.exact-virtual-surface').getBoundingClientRect();
    const top = Math.max(viewportBounds.top, surfaceBounds.top, 0);
    const bottom = Math.min(viewportBounds.top + viewport.clientHeight, surfaceBounds.bottom, innerHeight);
    const code = line.getBoundingClientRect();
    const thread = inline.getBoundingClientRect();
    if (code.top < top || code.bottom > bottom || thread.top < code.bottom || thread.bottom > bottom) return null;
    return {file, commitShortOid: oid, side: 'New', line: anchor.line, marker: anchor.marker,
      inlineThread: target, adjacentInlineRow: true, viewport: {top, bottom},
      code: {top: code.top, bottom: code.bottom}, thread: {top: thread.top, bottom: thread.bottom}};
  }

  function position(view) {
    return {cursor: view.cursor, focus: view.focus, scrollTop: view.scrollTop,
      targetOffset: view.targetOffset, archiveExpanded: view.archiveExpanded};
  }

  async function replay({target, orphan, anchor}) {
    await openArchive();
    const orphanObserved = await drive.until(`window.reviewReplay.inspectOrphan(${JSON.stringify(orphan)})`);
    await record('archive selected', target);
    const jPath = await focusThread(target);
    drive.key('k');
    await paint();
    requireValue(reading(target).cursor, jPath.at(-2), 'K selects preceding thread');
    drive.key('j');
    const beforeDiff = await record('before Enter', target);
    requireValue(beforeDiff.cursor, target, 'J restores target');
    requireValue(beforeDiff.archiveExpanded, 'true', 'Archives are expanded before the jump');
    requireValue(beforeDiff.scrollTop > 0, true, 'reading position is below the initial viewport');
    requireValue(beforeDiff.targetOffset >= 0 && beforeDiff.targetOffset < beforeDiff.viewportHeight,
      true, 'late thread starts inside the review viewport');
    requireValue([...beforeDiff.threadIds].sort(), archivedIds, 'archive thread identities before the jump');

    drive.key('Enter');
    const diff = await drive.until(`window.reviewReplay.inspectDiff(...${JSON.stringify([target, anchor])})`);
    observations.push({label: 'diff after Enter', ...diff});
    await drive.click('button', 'Close diff');
    await waitForReview('review-repo', archive, archivedIds);
    const afterDiff = await record('after Close diff', target);
    requireValue(position(afterDiff), {...position(beforeDiff), focus: target}, 'Close diff return position');

    await drive.click('tab', 'other-repo');
    await waitForReview('other-repo', 'Synthetic other repository review', ['other-control-thread']);
    const b = await record('other repository control', target);
    requireValue(b.threadIds, ['other-control-thread'], 'B owns its distinct review card');
    requireValue(b.archiveExpanded, null, 'A archive disclosure is absent on B');
    await drive.click('tab', 'review-repo');
    await waitForReview('review-repo', archive, archivedIds);
    const afterTabs = await record('after A/B/A', target);
    drive.key('j');
    const afterJ = await record('first J after A/B/A', target);
    const actual = position(afterTabs);
    const reset = {cursor: null, focus: null, scrollTop: 0,
      targetOffset: afterDiff.targetOffset + afterDiff.scrollTop, archiveExpanded: 'false'};
    const preserved = position(afterDiff);
    let tabReturnVerdict = 'other';
    if (equal(actual, reset) && afterJ.cursor === 'review-thread-01') tabReturnVerdict = 'reset';
    if (equal(actual, preserved) && afterJ.cursor === 'review-thread-13') tabReturnVerdict = 'preserved';
    return {anchorExpected: anchor, anchorObserved: diff, orphanObserved, jPath,
      diffReturn: {expected: {...position(beforeDiff), focus: target}, observed: afterDiff},
      tabControl: b, tabReturn: {reset, preserved, observed: afterTabs},
      firstJAfterTabs: afterJ.cursor, tabReturnVerdict};
  }

  window.reviewReplay = {
    replay, reviewReady, inspectDiff, inspectOrphan, observations,
    hasArchiveRow: () => Boolean(reviewRow(archive)),
  };
  return true;
})()
